1	/**
2	 * A content-addressed translation memory plus the batch driver both locale pipelines share.
3	 *
4	 * The pipelines used to re-translate every file on every run — one `claude -p` spawn per API
5	 * markdown file and per sidebar label. This module cuts that to the diff: each translatable unit is
6	 * keyed by a hash of its source text, so unchanged content is served from a committed cache and only
7	 * new or edited units reach the adapter. Small units (sidebar labels) are objectified into a single
8	 * batched request; large markdown is translated per file on a miss to keep fidelity.
9	 *
10	 * The flow is: diff (hash vs. cache) → objectify (batch the misses) → translate → destructure (map
11	 * results back by hash) → save (prune to the units seen this run, write JSON).
12	 *
13	 * @module
14	 */
15	import { join } from "node:path";
16	import {
17	  isPassthroughTranslation,
18	  resolveVerbatimAction,
19	  TranslationMemory as SharedTranslationMemory,
20	  sha256,
21	  type VerbatimPolicy,
22	} from "@pantoken/translation-adapters";
23	import type { TranslationAdapter } from "./api-translation.ts";
24	
25	/**
26	 * A translatable unit. `markdown` is translated per file (whole-file, e.g. guides); `text` (short
27	 * labels) and `prose` (block-level API/cssdoc prose) units are batched together into one request.
28	 */
29	export interface TranslationUnit {
30	  kind: "markdown" | "text" | "prose";
31	  source: string;
32	  /** Only used to label markdown units in adapter prompts/logs. */
33	  filePath?: string;
34	}
35	
36	/** The cache directory (committed — it's the reusable translation memory, not a build artifact). */
37	const cacheDir = join(import.meta.dirname, "..", "i18n-cache");
38	
39	/** The stable content key for a unit: `sha256(kind \0 source)`, hex. */
40	export function keyFor(kind: string, source: string): string {
41	  return sha256(`${kind}�${source}`);
42	}
43	
44	/** Docs facade: `(kind, source)` API over the shared memory; prunes to touched keys on save. */
45	export class TranslationMemory {
46	  private readonly _mem: SharedTranslationMemory;
47	  get path(): string {
48	    return this._mem.path;
49	  }
50	  get hits(): number {
51	    return this._mem.hits;
52	  }
53	  misses = 0;
54	
55	  private constructor(mem: SharedTranslationMemory) {
56	    this._mem = mem;
57	  }
58	
59	  /** Load (or start) the memory for `<locale>.<namespace>.json`. */
60	  static load(locale: string, namespace: string): TranslationMemory {
61	    const path = join(cacheDir, `${locale}.${namespace}.json`);
62	    return new TranslationMemory(SharedTranslationMemory.open(path, { prune: true }));
63	  }
64	
65	  get(kind: string, source: string): string | undefined {
66	    return this._mem.get(keyFor(kind, source));
67	  }
68	
69	  set(kind: string, source: string, translation: string): void {
70	    this._mem.set(keyFor(kind, source), translation);
71	    this.misses++;
72	  }
73	
74	  save(): void {
75	    this._mem.save();
76	  }
77	}
78	
79	/**
80	 * Translate a set of units against the memory. Returns a map keyed by `keyFor(kind, source)` so
81	 * callers can look up each unit's translation (identical sources collapse to one entry).
82	 *
83	 * Diff: cache hits are served immediately. Objectify + translate: `text` misses are deduped and sent
84	 * to {@link TranslationAdapter.translateBatch} in one request; `markdown` misses are translated per
85	 * file. Destructure + save: results are written back into the memory keyed by content hash.
86	 */
87	export interface TranslateOptions {
88	  /**
89	   * Persist the memory after each markdown miss, so a long run (e.g. hundreds of API files) is
90	   * resumable: if a translation fails partway, the completed work is already saved and a re-run
91	   * serves it from cache. Off by default.
92	   */
93	  autosave?: boolean;
94	  /**
95	   * Bypass the cache entirely: every unit is retranslated (and its cached value overwritten) even
96	   * when an unchanged cache hit already exists. Use this to force a fresh pass over already-cached
97	   * content (e.g. after fixing an adapter bug that produced bad translations). Defaults to the
98	   * `DOCS_TRANSLATION_FORCE` environment variable (`"1"` → `true`), so every caller —
99	   * `translate-guides.ts`, `translate-chrome.ts`, `translate-glossary.ts`, `translate-demos.ts`,
100	   * `build-api-locales.ts` — honors it without a code change.
101	   */
102	  force?: boolean;
103	  /**
104	   * Source strings allowed to legitimately match their translation verbatim (e.g. a code sample or
105	   * proper noun repeated across locales). Exempt from the passthrough guard: identical output for
106	   * these is cached normally, never stripped or warned about.
107	   */
108	  verbatimSources?: ReadonlySet<string>;
109	  /** Source strings copied directly into the result/cache without invoking the translation adapter. */
110	  requiredVerbatimSources?: ReadonlySet<string>;
111	  /** Fallback policy for source-identical translations by locale. */
112	  defaultVerbatim?: VerbatimPolicy;
113	  /** Locale resolved against {@link defaultVerbatim}. */
114	  locale?: string;
115	}
116	
117	/** True when an identical source value is explicitly allowed by the translation options. */
118	function allowsVerbatim(source: string, options: TranslateOptions): boolean {
119	  return (
120	    options.requiredVerbatimSources?.has(source) === true ||
121	    options.verbatimSources?.has(source) === true ||
122	    (options.locale !== undefined &&
123	      resolveVerbatimAction(options.defaultVerbatim, options.locale) === "allow")
124	  );
125	}
126	
127	/** Format optional locale and source provenance for a translation diagnostic. */
128	function translationContext(unit: TranslationUnit, options: TranslateOptions): string {
129	  const context = [options.locale, unit.filePath].filter((value) => value !== undefined).join(" ");
130	  return context === "" ? "" : ` [${context}]`;
131	}
132	
133	/**
134	 * Serve cache hits straight into `result` and return the deduped misses — one unit per unseen content
135	 * key, so an identical string (e.g. a repeated sidebar label) translates once. With `force`, every
136	 * cache lookup is skipped so every unit comes back as a miss instead.
137	 */
138	function diffAgainstCache(
139	  memory: TranslationMemory,
140	  units: readonly TranslationUnit[],
141	  result: Map<string, string>,
142	  force: boolean,
143	  options: TranslateOptions,
144	): TranslationUnit[] {
145	  const unique = new Map<string, TranslationUnit>();
146	  for (const unit of units) {
147	    const key = keyFor(unit.kind, unit.source);
148	    if (options.requiredVerbatimSources?.has(unit.source) === true) {
149	      const cached = memory.get(unit.kind, unit.source);
150	      if (cached !== unit.source) memory.set(unit.kind, unit.source, unit.source);
151	      result.set(key, unit.source);
152	      continue;
153	    }
154	    if (!force) {
155	      const cached = memory.get(unit.kind, unit.source);
156	      const isVerbatim = allowsVerbatim(unit.source, options);
157	      if (cached !== undefined && (isVerbatim || !isPassthroughTranslation(unit.source, cached))) {
158	        result.set(key, cached);
159	        continue;
160	      }
161	      if (cached !== undefined) {
162	        console.warn(
163	          `  !${translationContext(unit, options)} cached ${unit.kind} translation for ${JSON.stringify(unit.source.slice(0, 40))} looks untranslated; retranslating`,
164	        );
165	      }
166	    }
167	    if (!unique.has(key)) unique.set(key, unit);
168	  }
169	  return [...unique.values()];
170	}
171	
172	/** Translate each markdown miss per-file into `memory`/`result`; log and skip individual failures. */
173	async function translateMarkdownMisses(
174	  adapter: TranslationAdapter,
175	  memory: TranslationMemory,
176	  result: Map<string, string>,
177	  markdownMisses: readonly TranslationUnit[],
178	  options: TranslateOptions,
179	): Promise<void> {
180	  // Markdown: per-file (keeps fidelity; batching large bodies risks the model dropping structure).
181	  // A single file's failure is logged and skipped rather than aborting the whole run.
182	  for (const [index, unit] of markdownMisses.entries()) {
183	    try {
184	      const translated = await adapter.translateMarkdown(unit.source, unit.filePath ?? "");
185	      if (
186	        !allowsVerbatim(unit.source, options) &&
187	        isPassthroughTranslation(unit.source, translated)
188	      ) {
189	        console.warn(
190	          `  ! skipped ${unit.filePath ?? "a markdown unit"}: looks untranslated (identical to source), will retry next run`,
191	        );
192	        continue;
193	      }
194	      memory.set("markdown", unit.source, translated);
195	      result.set(keyFor("markdown", unit.source), translated);
196	      if (options.autosave) memory.save();
197	      // Markdown misses are per-file network round-trips (slow); log each one so long
198	      // runs don't sit silently — unlike the batched text/prose path, there's no other
199	      // progress signal until the whole file set for a locale finishes.
200	      console.log(
201	        `  … ${index + 1}/${markdownMisses.length} ${unit.filePath ?? "markdown unit"} translated`,
202	      );
203	    } catch (error) {
204	      console.warn(
205	        `  ! skipped ${unit.filePath ?? "a markdown unit"}: ${error instanceof Error ? error.message : String(error)}`,
206	      );
207	    }
208	  }
209	}
210	
211	/**
212	 * Translate the batchable (text + prose) misses in one objectified request (fewer round-trips),
213	 * streaming persistence + progress into `memory`/`result`. With `autosave`, a long cold run stays
214	 * resumable (a kill keeps completed chunks) and logs progress, instead of writing nothing until the
215	 * whole batch returns.
216	 */
217	async function translateBatchableMisses(
218	  adapter: TranslationAdapter,
219	  memory: TranslationMemory,
220	  result: Map<string, string>,
221	  batchable: readonly TranslationUnit[],
222	  options: TranslateOptions,
223	): Promise<void> {
224	  if (batchable.length === 0) return;
225	  const items = batchable.map((u) => ({ id: keyFor(u.kind, u.source), text: u.source }));
226	  const byId = new Map(items.map((item, index) => [item.id, batchable[index]]));
227	  const consumed = new Set<string>();
228	  const persist = (partial: Record<string, string>): void => {
229	    let added = 0;
230	    for (const [id, value] of Object.entries(partial)) {
231	      const unit = byId.get(id);
232	      if (unit === undefined || consumed.has(id)) continue;
233	      consumed.add(id);
234	      if (!allowsVerbatim(unit.source, options) && isPassthroughTranslation(unit.source, value)) {
235	        console.warn(
236	          `  !${translationContext(unit, options)} ${unit.kind} unit looks untranslated (identical to source), not cached: ${JSON.stringify(unit.source.slice(0, 40))}`,
237	        );
238	        result.set(id, unit.source);
239	        continue; // not cached — stays a miss, retried next run
240	      }
241	      memory.set(unit.kind, unit.source, value);
242	      result.set(id, value);
243	      added += 1;
244	    }
245	    if (added === 0) return; // e.g. the final sweep re-seeing an already-persisted chunk
246	    if (options.autosave) memory.save();
247	    if (items.length > 1) {
248	      console.log(`  … ${consumed.size}/${items.length} labels + prose blocks translated`);
249	    }
250	  };
251	
252	  const batched = adapter.translateBatch
253	    ? await adapter.translateBatch(items, persist)
254	    : Object.fromEntries(
255	        await Promise.all(
256	          items.map(async (i) => [i.id, await adapter.translateText(i.text)] as const),
257	        ),
258	      );
259	  // Cover adapters that didn't stream through the callback (the per-item fallback above).
260	  persist(batched);
261	  // Anything still missing — a chunk that errored out, or a key the model dropped — renders as its
262	  // source text this run but is NOT cached, so it stays a miss and is retried next run rather than
263	  // being frozen as English in the committed memory.
264	  for (const unit of batchable) {
265	    const key = keyFor(unit.kind, unit.source);
266	    if (consumed.has(key)) continue;
267	    consumed.add(key);
268	    result.set(key, unit.source);
269	  }
270	}
271	
272	/**
273	 * Translate a set of units, serving cache hits from `memory` and translating the misses through
274	 * `adapter`. Returns a map from each unit's key to its translated (or passthrough) text.
275	 *
276	 * @param adapter - The translation engine for cache misses.
277	 * @param memory - The persisted translation cache.
278	 * @param units - The units to translate.
279	 * @param options - Optional translation settings.
280	 * @returns A map keyed by each unit's cache key.
281	 */
282	export async function translateUnits(
283	  adapter: TranslationAdapter,
284	  memory: TranslationMemory,
285	  units: readonly TranslationUnit[],
286	  options: TranslateOptions = {},
287	): Promise<Map<string, string>> {
288	  const result = new Map<string, string>();
289	  const force = options.force ?? process.env.DOCS_TRANSLATION_FORCE === "1";
290	
291	  const misses = diffAgainstCache(memory, units, result, force, options);
292	  const markdownMisses = misses.filter((u) => u.kind === "markdown");
293	  const textMisses = misses.filter((u) => u.kind === "text");
294	  const proseMisses = misses.filter((u) => u.kind === "prose");
295	
296	  await translateMarkdownMisses(adapter, memory, result, markdownMisses, options);
297	
298	  // Poison-cache guard: an adapter that can't translate prose (the glossary) would only pass a prose
299	  // block through near-unchanged. Serve that passthrough into the rendered file, but DON'T cache it —
300	  // caching it under the prose key would permanently mask the block from a later claude run, since the
301	  // content hash wouldn't change. It must stay a miss.
302	  const batchable = [...textMisses];
303	  if (adapter.translatesProse === false) {
304	    for (const unit of proseMisses) result.set(keyFor("prose", unit.source), unit.source);
305	  } else {
306	    batchable.push(...proseMisses);
307	  }
308	
309	  await translateBatchableMisses(adapter, memory, result, batchable, options);
310	
311	  return result;
312	}
