1	/**
2	 * Locale translation adapter primitives for generated API docs.
3	 *
4	 * The default adapter is deterministic and keyless (safe for CI), while the adapter contract keeps
5	 * room for higher-quality engines later.
6	 */
7	import { extractJsonObject, spawnPrompt } from "@pantoken/translation-adapters";
8	import { CANVAS_LOCALES } from "@pantoken/i18n";
9	import { GLOSSARY_TERMS, type GlossaryKind } from "./glossary.ts";
10	import { TranslationMemory } from "./translation-memory.ts";
11	
12	// English display name per locale (e.g. "Hungarian (Magyar)" \u2192 the adapter prompt only needs the
13	// leading English name, not the native parenthetical), used to phrase the `AiTranslationAdapter`
14	// prompt for any target locale instead of a hardcoded "Hungarian". The three English regional variants
15	// are named explicitly instead — stripping their parenthetical would collapse all three (and root) to
16	// the bare word "English", losing the spelling/phrasing distinction (colour vs. color, etc.) the prompt
17	// needs to actually produce a localized (not identical) translation.
18	const ENGLISH_VARIANT_LABELS: Record<string, string> = {
19	  "en-AU": "Australian English",
20	  "en-CA": "Canadian English",
21	  "en-GB": "British English",
22	};
23	
24	const LOCALE_LABELS: Record<string, string> = Object.fromEntries(
25	  Object.entries(CANVAS_LOCALES).map(([locale, meta]) => [
26	    locale,
27	    ENGLISH_VARIANT_LABELS[locale] ?? meta.label.replace(/\s*\(.*\)$/, ""),
28	  ]),
29	);
30	
31	/** A pluggable translation engine: named, with markdown/text/batch translate methods. */
32	export interface TranslationAdapter {
33	  readonly name: string;
34	  /**
35	   * Whether this adapter produces real prose translations. The glossary sets this `false`: it only
36	   * knows structural terms, so the pipeline must not treat its passthrough of a prose block as a
37	   * translation (see the poison-cache guard in `translation-memory.ts`). Defaults to `true`.
38	   */
39	  readonly translatesProse?: boolean;
40	  translateMarkdown(input: string, filePath: string): Promise<string>;
41	  translateText(input: string): Promise<string>;
42	  /**
43	   * Translate many short strings in one request. Returns a map keyed by each item's `id`. Optional:
44	   * callers fall back to per-item {@link TranslationAdapter.translateText} when it's absent.
45	   *
46	   * `onChunk` (if given) is called with each chunk's partial results as it completes, so a caller can
47	   * persist and report progress mid-run rather than only after the whole batch returns. Chunks may
48	   * run concurrently, so `onChunk` can fire out of order.
49	   */
50	  translateBatch?(
51	    items: readonly { id: string; text: string }[],
52	    onChunk?: (partial: Record<string, string>) => void,
53	  ): Promise<Record<string, string>>;
54	}
55	
56	/** Escape regex metacharacters so a glossary term can be dropped into a `RegExp` literally. */
57	const escapeRegExp = (value: string): string => value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
58	
59	/** Build the match pattern for a glossary term, based on how it's shaped in generated markdown. */
60	const patternFor = (kind: GlossaryKind, term: string): RegExp => {
61	  const escaped = escapeRegExp(term);
62	  switch (kind) {
63	    case "heading":
64	      return new RegExp(`^(#{1,6} )${escaped}$`, "gm");
65	    case "line":
66	      return new RegExp(`^${escaped}$`, "g");
67	    case "badge":
68	      return new RegExp(`(pantoken-doc-tag">)${escaped}(<)`, "g");
69	    default:
70	      return new RegExp(`\\b${escaped}\\b`, "g");
71	  }
72	};
73	
74	/** Build the replacement string for a translated term, preserving any capture groups `patternFor` used. */
75	const replacementFor = (kind: GlossaryKind, translated: string): string => {
76	  switch (kind) {
77	    case "heading":
78	      return `$1${translated}`;
79	    case "badge":
80	      return `$1${translated}$2`;
81	    default:
82	      return translated;
83	  }
84	};
85	
86	/**
87	 * Deterministic adapter: substitutes known structural terms only (headings, badges, table labels),
88	 * looked up from the `<locale>.glossary.json` translation-memory cache (see `glossary.ts` for the term
89	 * list and `translate-glossary.ts` for how the cache is filled). It can't translate prose, so
90	 * `translatesProse` is `false`. Safe to run in CI — it never spawns an adapter or hits the network.
91	 */
92	export class GlossaryTranslationAdapter implements TranslationAdapter {
93	  readonly name = "glossary";
94	  // Deterministic term substitution only — it cannot translate prose, so the memory must never cache
95	  // its output under a prose key.
96	  readonly translatesProse = false;
97	  private readonly replacements: Array<[RegExp, string]>;
98	
99	  constructor(locale = "hu") {
100	    const memory = TranslationMemory.load(locale, "glossary");
101	    // Untranslated terms are skipped (identity passthrough) rather than matched against an empty
102	    // string, so an in-progress locale still renders every OTHER already-translated term correctly.
103	    this.replacements = GLOSSARY_TERMS.flatMap(({ kind, term }) => {
104	      const translated = memory.get("text", term);
105	      if (translated === undefined) return [];
106	      return [[patternFor(kind, term), replacementFor(kind, translated)] as [RegExp, string]];
107	    });
108	  }
109	
110	  translateMarkdown(input: string): Promise<string> {
111	    return Promise.resolve(translateWithoutFencedCode(input, (text) => this.translateSync(text)));
112	  }
113	
114	  translateText(input: string): Promise<string> {
115	    return Promise.resolve(this.translateSync(input));
116	  }
117	
118	  /** The deterministic core — synchronous; the async methods just wrap it to satisfy the contract. */
119	  private translateSync(input: string): string {
120	    const preserved = preservePackageNames(input);
121	    let out = preserved.text;
122	    for (const [pattern, value] of this.replacements) {
123	      out = out.replace(pattern, value);
124	    }
125	    return restorePackageNames(out, preserved.packageNames);
126	  }
127	
128	  translateBatch(
129	    items: readonly { id: string; text: string }[],
130	    onChunk?: (partial: Record<string, string>) => void,
131	  ): Promise<Record<string, string>> {
132	    const out = Object.fromEntries(items.map((item) => [item.id, this.translateSync(item.text)]));
133	    onChunk?.(out);
134	    return Promise.resolve(out);
135	  }
136	}
137	
138	const replaceBlocks = (
139	  input: string,
140	  pattern: RegExp,
141	  markerPrefix: string,
142	): { text: string; blocks: string[] } => {
143	  const blocks: string[] = [];
144	  const text = input.replace(pattern, (match) => {
145	    const marker = `__${markerPrefix}_${blocks.length}__`;
146	    blocks.push(match);
147	    return marker;
148	  });
149	  return { text, blocks };
150	};
151	
152	const restoreBlocks = (input: string, blocks: string[], markerPrefix: string): string => {
153	  let out = input;
154	  for (const [index, block] of blocks.entries()) {
155	    out = out.replaceAll(`__${markerPrefix}_${index}__`, block);
156	  }
157	  return out;
158	};
159	
160	const preserveMarkdownSensitiveBlocks = (
161	  input: string,
162	): {
163	  text: string;
164	  codeBlocks: string[];
165	  inlineCodeBlocks: string[];
166	} => {
167	  const fenced = replaceBlocks(input, /```[\s\S]*?```/g, "PTK_CODE_BLOCK");
168	  const inline = replaceBlocks(fenced.text, /`[^`\n]+`/g, "PTK_INLINE_CODE");
169	  return {
170	    text: inline.text,
171	    codeBlocks: fenced.blocks,
172	    inlineCodeBlocks: inline.blocks,
173	  };
174	};
175	
176	const restoreMarkdownSensitiveBlocks = (
177	  input: string,
178	  codeBlocks: string[],
179	  inlineCodeBlocks: string[],
180	): string => {
181	  const withCode = restoreBlocks(input, codeBlocks, "PTK_CODE_BLOCK");
182	  return restoreBlocks(withCode, inlineCodeBlocks, "PTK_INLINE_CODE");
183	};
184	
185	const preservePackageNames = (input: string): { text: string; packageNames: string[] } => {
186	  const packagePattern = /@[a-z0-9][a-z0-9.-]*\/[a-z0-9][a-z0-9.-]*/gi;
187	  const packageNames: string[] = [];
188	
189	  const text = input.replace(packagePattern, (match) => {
190	    const marker = `__PTK_PACKAGE_${packageNames.length}__`;
191	    packageNames.push(match);
192	    return marker;
193	  });
194	
195	  return { text, packageNames };
196	};
197	
198	const restorePackageNames = (input: string, packageNames: string[]): string => {
199	  let out = input;
200	  for (const [index, packageName] of packageNames.entries()) {
201	    out = out.replaceAll(`__PTK_PACKAGE_${index}__`, packageName);
202	  }
203	  return out;
204	};
205	
206	// TypeDoc renders a generic type as several separately backtick-wrapped tokens joined by bare escaped
207	// angle brackets (e.g. `` `Readonly`\<`Record`\<`string`, `string`\>\> ``) — each `` `Token` `` is
208	// masked on its own by preserveMarkdownSensitiveBlocks, but the `\<`/`\>` glue between them is NOT (it's
209	// outside any code span), so it reaches the model as bare punctuation in an otherwise-prose sentence or
210	// caption. Asked to "translate" text containing that, a model has duplicated/mangled the brackets
211	// (`\>` → `>>>>>>>\>`) rather than leaving them alone. Masking them unconditionally, everywhere text
212	// reaches the model, removes the ambiguity instead of relying on the model to recognize and preserve it.
213	const ESCAPED_ANGLE_BRACKET = /\\[<>]/g;
214	
215	const preserveEscapedAngleBrackets = (input: string): { text: string; brackets: string[] } => {
216	  const brackets: string[] = [];
217	  const text = input.replace(ESCAPED_ANGLE_BRACKET, (match) => {
218	    const marker = `__PTK_ESC_${brackets.length}__`;
219	    brackets.push(match);
220	    return marker;
221	  });
222	  return { text, brackets };
223	};
224	
225	const restoreEscapedAngleBrackets = (input: string, brackets: string[]): string => {
226	  let out = input;
227	  for (const [index, bracket] of brackets.entries()) {
228	    out = out.replaceAll(`__PTK_ESC_${index}__`, bracket);
229	  }
230	  return out;
231	};
232	
233	const translateWithoutFencedCode = (input: string, translate: (line: string) => string): string => {
234	  const lines = input.split("\n");
235	  const out: string[] = [];
236	  let inFence = false;
237	
238	  for (const line of lines) {
239	    if (line.trimStart().startsWith("```")) {
240	      inFence = !inFence;
241	      out.push(line);
242	      continue;
243	    }
244	
245	    if (inFence) {
246	      out.push(line);
247	      continue;
248	    }
249	
250	    out.push(translate(line));
251	  }
252	
253	  return out.join("\n");
254	};
255	
256	/** Group items into chunks that each stay within `budget` characters, never splitting an item. */
257	const chunkByBudget = (
258	  items: readonly { id: string; text: string }[],
259	  budget: number,
260	): { id: string; text: string }[][] => {
261	  const chunks: { id: string; text: string }[][] = [];
262	  let chunk: { id: string; text: string }[] = [];
263	  let size = 0;
264	  for (const item of items) {
265	    if (size + item.text.length > budget && chunk.length > 0) {
266	      chunks.push(chunk);
267	      chunk = [];
268	      size = 0;
269	    }
270	    chunk.push(item);
271	    size += item.text.length;
272	  }
273	  if (chunk.length > 0) chunks.push(chunk);
274	  return chunks;
275	};
276	
277	/** Run `tasks` with at most `limit` in flight at once, preserving result order. */
278	const mapPool = async <T, R>(
279	  tasks: readonly T[],
280	  limit: number,
281	  fn: (task: T, index: number) => Promise<R>,
282	): Promise<R[]> => {
283	  const results: R[] = Array.from({ length: tasks.length });
284	  let next = 0;
285	  const worker = async (): Promise<void> => {
286	    while (next < tasks.length) {
287	      const index = next++;
288	      results[index] = await fn(tasks[index], index);
289	    }
290	  };
291	  await Promise.all(Array.from({ length: Math.min(limit, tasks.length) }, worker));
292	  return results;
293	};
