295	/**
296	 * Adapter that shells out to the Claude Code CLI (configurable via `DOCS_TRANSLATION_COMMAND` and
297	 * `DOCS_TRANSLATION_COMMAND_ARGS`) to produce real prose translations.
298	 */
299	export class AiTranslationAdapter implements TranslationAdapter {
300	  readonly name = "ai";
301	
302	  private readonly command: string;
303	  private readonly args: string[];
304	  private readonly targetLanguage: string;
305	
306	  constructor(locale = "hu") {
307	    this.command = process.env.DOCS_TRANSLATION_COMMAND ?? "claude";
308	    this.args = (process.env.DOCS_TRANSLATION_COMMAND_ARGS ?? "")
309	      .split(" ")
310	      .map((part) => part.trim())
311	      .filter((part) => part.length > 0);
312	    this.targetLanguage = LOCALE_LABELS[locale] ?? locale;
313	  }
314	
315	  async translateMarkdown(input: string, filePath: string): Promise<string> {
316	    const preservedMarkdown = preserveMarkdownSensitiveBlocks(input);
317	    const preservedPackages = preservePackageNames(preservedMarkdown.text);
318	    const preservedBrackets = preserveEscapedAngleBrackets(preservedPackages.text);
319	    const prompt = [
320	      `Translate this technical markdown from English to ${this.targetLanguage}.`,
321	      "Return only the translated markdown.",
322	      "Rules:",
323	      "- Keep markdown structure unchanged.",
324	      "- Translate heading text too (the words after the leading # symbols) — do not leave headings in English.",
325	      "- Do not alter placeholder tokens like __PTK_CODE_BLOCK_#__ or __PTK_INLINE_CODE_#__.",
326	      "- Do not alter placeholder tokens like __PTK_PACKAGE_#__ or __PTK_ESC_#__.",
327	      "- Preserve whitespace and line breaks.",
328	      "- Keep import paths, package names, URLs, and identifiers intact.",
329	      `File: ${filePath}`,
330	      "--- BEGIN MARKDOWN ---",
331	      preservedBrackets.text,
332	      "--- END MARKDOWN ---",
333	    ].join("\n");
334	
335	    const translated = await this.runClaude(prompt, `markdown file ${filePath}`);
336	    const restoredBrackets = restoreEscapedAngleBrackets(translated, preservedBrackets.brackets);
337	    const restoredPackages = restorePackageNames(restoredBrackets, preservedPackages.packageNames);
338	    return restoreMarkdownSensitiveBlocks(
339	      restoredPackages,
340	      preservedMarkdown.codeBlocks,
341	      preservedMarkdown.inlineCodeBlocks,
342	    );
343	  }
344	
345	  async translateText(input: string): Promise<string> {
346	    const preserved = preservePackageNames(input);
347	    const preservedBrackets = preserveEscapedAngleBrackets(preserved.text);
348	    const prompt = [
349	      `Translate this technical UI text from English to ${this.targetLanguage}.`,
350	      "Return only the translation.",
351	      "Keep identifiers and package names unchanged.",
352	      "Do not alter placeholder tokens like __PTK_PACKAGE_#__ or __PTK_ESC_#__.",
353	      "Text:",
354	      preservedBrackets.text,
355	    ].join("\n");
356	
357	    const translated = (await this.runClaude(prompt, "single text line")).trim();
358	    const restoredBrackets = restoreEscapedAngleBrackets(translated, preservedBrackets.brackets);
359	    return restorePackageNames(restoredBrackets, preserved.packageNames);
360	  }
361	
362	  async translateBatch(
363	    items: readonly { id: string; text: string }[],
364	    onChunk?: (partial: Record<string, string>) => void,
365	  ): Promise<Record<string, string>> {
366	    // Split into character-budgeted chunks. Each chunk is one `claude -p` call; because the run is
367	    // generation-bound (the model streaming ~a chunk's worth of translations dominates the fixed
368	    // startup), running several chunks concurrently is the real wall-clock lever. Smaller chunks keep
369	    // each JSON response reliable and give finer progress; the pool hides their startup cost.
370	    const BUDGET = Number(process.env.DOCS_TRANSLATION_BATCH_BUDGET) || 4000;
371	    const CONCURRENCY = Number(process.env.DOCS_TRANSLATION_CONCURRENCY) || 5;
372	    const chunks = chunkByBudget(items, BUDGET);
373	
374	    const out: Record<string, string> = {};
375	    await mapPool(chunks, CONCURRENCY, async (group) => {
376	      // A failed chunk must not sink the whole run or poison the cache: log it and skip. Its items go
377	      // uncached (the caller leaves them as source), so they're retried on the next run.
378	      try {
379	        const partial = await this.runBatch(group);
380	        Object.assign(out, partial);
381	        // Surface each chunk as it lands so the caller can persist + report progress.
382	        onChunk?.(partial);
383	      } catch (error) {
384	        console.warn(
385	          `  ! skipped a batch of ${group.length} strings: ${error instanceof Error ? error.message : String(error)}`,
386	        );
387	      }
388	    });
389	    return out;
390	  }
391	
392	  /** Translate one chunk of short strings as a single JSON object; fall back per item on failure. */
393	  private async runBatch(
394	    items: readonly { id: string; text: string }[],
395	  ): Promise<Record<string, string>> {
396	    // Protect code, package names, and escaped generic-type brackets in every value before it reaches
397	    // the model — prose cells and captions carry inline code, `@scope/pkg` names, and TypeDoc's
398	    // `` `Foo`\<`Bar`\> `` bracket glue that must survive verbatim — then restore per id. Without this
399	    // the batch path (unlike translateMarkdown) would let the model rewrite them.
400	    const masked = items.map((item) => {
401	      const markdown = preserveMarkdownSensitiveBlocks(item.text);
402	      const packages = preservePackageNames(markdown.text);
403	      const brackets = preserveEscapedAngleBrackets(packages.text);
404	      return { id: item.id, masked: brackets.text, markdown, packages, brackets };
405	    });
406	    const restore = (entry: (typeof masked)[number], value: string): string =>
407	      restoreMarkdownSensitiveBlocks(
408	        restorePackageNames(
409	          restoreEscapedAngleBrackets(value, entry.brackets.brackets),
410	          entry.packages.packageNames,
411	        ),
412	        entry.markdown.codeBlocks,
413	        entry.markdown.inlineCodeBlocks,
414	      );
415	
416	    const payload = Object.fromEntries(masked.map((entry) => [entry.id, entry.masked]));
417	    const prompt = [
418	      `Translate the VALUES of this JSON object from English to ${this.targetLanguage}.`,
419	      "Return ONLY a JSON object with the same keys and translated values.",
420	      "Do not translate, add, or remove keys. Keep identifiers, package names, and URLs unchanged.",
421	      "Do not alter placeholder tokens like __PTK_CODE_BLOCK_#__, __PTK_INLINE_CODE_#__, __PTK_PACKAGE_#__, or __PTK_ESC_#__.",
422	      JSON.stringify(payload, null, 2),
423	    ].join("\n");
424	
425	    const raw = await this.runClaude(prompt, `batch of ${items.length} strings`);
426	    const parsed = extractJsonObject(raw);
427	    if (parsed) {
428	      const out: Record<string, string> = {};
429	      for (const entry of masked) {
430	        const value = parsed[entry.id];
431	        // A missing/non-string value restores to the (masked → original) source rather than dropping it.
432	        out[entry.id] = restore(entry, typeof value === "string" ? value : entry.masked);
433	      }
434	      return out;
435	    }
436	    // The model didn't return usable JSON; degrade to per-item translation rather than lose content.
437	    const out: Record<string, string> = {};
438	    for (const item of items) out[item.id] = await this.translateText(item.text);
439	    return out;
440	  }
441	
442	  private runClaude(prompt: string, scope: string): Promise<string> {
443	    return spawnPrompt(this.command, [...this.args, "-p"], prompt, scope);
444	  }
445	}
446	
447	/**
448	 * Build the adapter named by `DOCS_TRANSLATION_ADAPTER` (default `glossary`), targeting `locale`
449	 * (default `hu`, kept as the default for backward-compatible callers). Throws on an unknown name.
450	 * Supported values are `glossary` and `ai`.
451	 */
452	export const createTranslationAdapter = (locale = "hu"): TranslationAdapter => {
453	  // A pluggable selector means we can drop in a richer provider later without changing callers.
454	  const selected = (process.env.DOCS_TRANSLATION_ADAPTER ?? "glossary").toLowerCase();
455	
456	  if (selected === "glossary") {
457	    return new GlossaryTranslationAdapter(locale);
458	  }
459	
460	  if (selected === "ai") {
461	    return new AiTranslationAdapter(locale);
462	  }
463	
464	  throw new Error(
465	    `Unsupported DOCS_TRANSLATION_ADAPTER: ${selected}. Supported adapters: glossary, ai`,
466	  );
467	};
