1	/**
2	 * Split a self-hosted demo HTML template (`docs/demos/<component>/index.html`) into translatable prose
3	 * text nodes vs.
4	 * verbatim markup, so `translate-demos.ts` can localize captions/labels without touching tags,
5	 * attributes (including `aria-*`/`title`), comments, or `<script>`/`<style>` contents.
6	 *
7	 * Deliberately narrower than a real HTML parser: it only needs to find text runs between tags outside
8	 * `<script>`/`<style>`, which these small, hand-written demo fragments never nest ambiguously.
9	 * `reassembleDemoHtml(segmentDemoHtml(html), (t) => t)` is the identity — the split is lossless.
10	 *
11	 * @module
12	 */
13	
14	/** One run of a segmented demo HTML fragment — translatable prose or verbatim markup. */
15	export interface DemoSegment {
16	  kind: "prose" | "preserve";
17	  text: string;
18	}
19	
20	/** Segment `html` into prose (translatable text nodes) and preserve (tags, comments, script/style) runs. */
21	export function segmentDemoHtml(html: string): DemoSegment[] {
22	  const segments: DemoSegment[] = [];
23	  let i = 0;
24	  let inScript = false;
25	  let inStyle = false;
26	  // <code> wraps inline snippets (attribute/class names like `transition="fade"`, `-without-shadow`)
27	  // that read as prose (they contain letters) but must stay verbatim, same as markdown inline code.
28	  let inCode = false;
29	
30	  while (i < html.length) {
31	    if (html.startsWith("<!--", i)) {
32	      const end = html.indexOf("-->", i + 4);
33	      const stop = end === -1 ? html.length : end + 3;
34	      segments.push({ kind: "preserve", text: html.slice(i, stop) });
35	      i = stop;
36	      continue;
37	    }
38	
39	    if (html[i] === "<") {
40	      const close = html.indexOf(">", i);
41	      const stop = close === -1 ? html.length : close + 1;
42	      const tagText = html.slice(i, stop);
43	      segments.push({ kind: "preserve", text: tagText });
44	      const nameMatch = /^<\/?\s*([a-zA-Z][\w-]*)/.exec(tagText);
45	      const name = nameMatch?.[1]?.toLowerCase();
46	      const isClosing = tagText.startsWith("</");
47	      if (name === "script") inScript = !isClosing;
48	      if (name === "style") inStyle = !isClosing;
49	      if (name === "code") inCode = !isClosing;
50	      i = stop;
51	      continue;
52	    }
53	
54	    const nextTag = html.indexOf("<", i);
55	    const stop = nextTag === -1 ? html.length : nextTag;
56	    const text = html.slice(i, stop);
57	    // Only a run with a letter is worth translating — pure whitespace/punctuation/numbers stay verbatim.
58	    const isProse = !inScript && !inStyle && !inCode && /\p{L}/u.test(text);
59	    segments.push({ kind: isProse ? "prose" : "preserve", text });
60	    i = stop;
61	  }
62	
63	  return segments;
64	}
65	
66	/** Collect the unique prose texts in `segments`, in first-seen order. */
67	export function collectDemoUnits(segments: readonly DemoSegment[]): string[] {
68	  const seen = new Set<string>();
69	  for (const segment of segments) {
70	    if (segment.kind === "prose") seen.add(segment.text);
71	  }
72	  return [...seen];
73	}
74	
75	/** Rebuild HTML from `segments`, translating each prose run through `resolve`. */
76	export function reassembleDemoHtml(
77	  segments: readonly DemoSegment[],
78	  resolve: (text: string) => string,
79	): string {
80	  return segments.map((s) => (s.kind === "prose" ? resolve(s.text) : s.text)).join("");
81	}
