1	/**
2	 * Split generated API markdown into translatable segments.
3	 *
4	 * The locale pipeline used to hash and translate whole `.md` files. Generated docs churn on every
5	 * build (stability-badge flips, resolved token values, signature edits), so a whole-file key thrashed
6	 * and the page's prose reverted to English. This module cuts the file into blocks so only real prose
7	 * carries a content key — the scaffolding around it can change without busting the cache.
8	 *
9	 * Each segment is one of:
10	 * - `preserve` — emitted verbatim (code fences, signatures, breadcrumbs, type/link-only lines, HTML).
11	 * - `glossary` — deterministic term substitution (section headings, stability-badge pills, table
12	 *   column labels). Cheap, keyless, never cached.
13	 * - `prose`    — real translation (descriptions, remarks, `@example` captions, table Description cells).
14	 * - `table`    — a GFM table parsed into a grid so header labels + Description cells translate while
15	 *   code columns and structure stay verbatim. Only emitted when the grid rebuilds byte-for-byte to the
16	 *   source (see the round-trip self-check); otherwise the table falls back to `preserve`.
17	 *
18	 * `reassemble(segmentMarkdown(md), (t) => t)` is the identity — the split is lossless.
19	 *
20	 * @module
21	 */
22	
23	/** How a translatable segment is handled: cheap `glossary` substitution or real `prose` translation. */
24	export type TranslationKind = "glossary" | "prose";
25	
26	/**
27	 * The marker `docs/scripts/build-css-api.ts` prepends to its JS Requirement/Enhancement callout
28	 * (`jsRequirementCallout`) — recognized here so the bold label and note translate instead of the
29	 * whole block being swallowed by the generic blockquote `preserve` rule below.
30	 */
31	export const JS_CALLOUT_MARKER = "<!-- js-requirement -->";
32	
33	/** One block of split markdown, tagged by how it should be emitted or translated. */
34	export type Segment =
35	  | { kind: "preserve"; text: string }
36	  | { kind: "glossary"; text: string }
37	  | { kind: "prose"; text: string }
38	  | {
39	      kind: "table";
40	      rows: string[][];
41	      headerRow: number;
42	      separatorRow: number;
43	      /** Column indices whose body cells hold prose (a `Description`/`Summary` column). */
44	      descCols: number[];
45	    }
46	  | {
47	      /** The `<!-- js-requirement -->` callout: `marker`/`alertLine` are verbatim, `label` (e.g.
48	       *  "JS Requirement"/"JS Enhancement") is a fixed glossary term, `note` is real prose. */
49	      kind: "callout";
50	      marker: string;
51	      alertLine: string;
52	      label: string;
53	      note: string;
54	    };
55	
56	/** A translatable unit: source text plus how it should be translated. */
57	export interface TranslatableUnit {
58	  text: string;
59	  kind: TranslationKind;
60	}
61	
62	/** How to resolve a translatable unit to its target text. Identity round-trips the source. */
63	export type Resolve = (text: string, kind: TranslationKind) => string;
64	
65	/** Strip inline code, markdown links, and HTML tags, then keep only Latin letters. */
66	const stripNonProse = (input: string): string =>
67	  input
68	    .replace(/`[^`]*`/g, " ")
69	    .replace(/\[[^\]]*\]\([^)]*\)/g, " ")
70	    .replace(/<[^>]+>/g, " ")
71	    .replace(/[^A-Za-z]+/g, " ")
72	    .trim();
73	
74	const hasProseWords = (input: string): boolean => stripNonProse(input).length > 0;
75	
76	/** A breadcrumb line: starts with a link and chains crumbs with ` / ` (the trailing crumb is plain). */
77	const isBreadcrumb = (line: string): boolean =>
78	  /^\[[^\]]+\]\([^)]+\)/.test(line) && line.includes(" / ");
79	
80	/** An em-dash-only or blank table cell carries no prose. */
81	const isEmptyCell = (cell: string): boolean => cell === "" || cell === "—" || cell === "-";
82	
83	/** A body cell worth translating: has prose words and isn't an empty placeholder. */
84	const isTranslatableCell = (cell: string): boolean => !isEmptyCell(cell) && hasProseWords(cell);
85	
86	/** A cell carrying a stability-badge pill localizes deterministically, not through the prose engine. */
87	const cellKind = (cell: string): TranslationKind =>
88	  cell.includes("pantoken-doc-tag") ? "glossary" : "prose";
89	
90	const FENCE = /^\s*```/;
91	
92	/** Split a table row into trimmed cells, honoring `\|`-escaped pipes inside cells. */
93	const parseRow = (line: string): string[] => {
94	  let inner = line.trim();
95	  if (inner.startsWith("|")) inner = inner.slice(1);
96	  if (inner.endsWith("|")) inner = inner.slice(0, -1);
97	  return inner.split(/(?<!\\)\|/).map((cell) => cell.trim());
98	};
99	
100	const rebuildRow = (cells: string[]): string => `| ${cells.join(" | ")} |`;
101	
102	/** A GFM separator row: every cell is `---`, `:--`, `--:`, or `:-:`. */
103	const isSeparatorRow = (line: string): boolean => {
104	  const cells = parseRow(line);
105	  return cells.length > 0 && cells.every((cell) => /^:?-+:?$/.test(cell));
106	};
107	
108	const CALLOUT_LINE_RE = /^> \*\*(.+?)\*\* — (.+)$/u;
109	
110	/**
111	 * The `<!-- js-requirement -->`-marked callout `build-css-api.ts` emits: `marker` + `> [!TIP]` +
112	 * `> **{label}** — {note}`. Only classified as `"callout"` when it rebuilds byte-for-byte to the
113	 * source (mirrors the table round-trip guard); otherwise `undefined`, and the generic blockquote
114	 * `preserve` rule in {@link classifyBlock} takes over.
115	 */
116	const classifyJsCallout = (lines: string[]): Segment | undefined => {
117	  if (lines.length !== 3 || lines[0] !== JS_CALLOUT_MARKER || lines[1] !== "> [!TIP]")
118	    return undefined;
119	  const match = CALLOUT_LINE_RE.exec(lines[2]);
120	  if (!match) return undefined;
121	  const [, label, note] = match;
122	  return { kind: "callout", marker: lines[0], alertLine: lines[1], label, note };
123	};
124	
125	/** Classify a run of consecutive non-blank, non-fenced lines. */
126	const classifyBlock = (lines: string[]): Segment => {
127	  const text = lines.join("\n");
128	  const first = lines[0];
129	
130	  // Table: header row + separator. Only translate cells when the grid rebuilds exactly to the source,
131	  // so anything with unexpected spacing/escaping is preserved whole rather than silently reformatted.
132	  if (lines.length >= 2 && first.trimStart().startsWith("|") && isSeparatorRow(lines[1])) {
133	    const rows = lines.map(parseRow);
134	    if (rows.map(rebuildRow).join("\n") === text) {
135	      const descCols = rows[0]
136	        .map((header, index) => (/^(description|summary)$/i.test(header) ? index : -1))
137	        .filter((index) => index >= 0);
138	      return { kind: "table", rows, headerRow: 0, separatorRow: 1, descCols };
139	    }
140	    return { kind: "preserve", text };
141	  }
142	
143	  const callout = classifyJsCallout(lines);
144	  if (callout) return callout;
145	
146	  // Headings and stability-badge pills → deterministic glossary. The glossary no-ops on identifiers
147	  // (`### options?`) and on words it doesn't know, so routing every heading here is safe.
148	  if (/^#{1,6}\s/.test(first)) return { kind: "glossary", text };
149	  if (first.trimStart().startsWith("<")) {
150	    return { kind: text.includes("pantoken-doc-tag") ? "glossary" : "preserve", text };
151	  }
152	
153	  // Signatures/blockquotes, breadcrumbs, and lines that are only links/code/type expressions.
154	  if (first.trimStart().startsWith(">")) return { kind: "preserve", text };
155	  if (isBreadcrumb(first)) return { kind: "preserve", text };
156	  if (!hasProseWords(text)) return { kind: "preserve", text };
157	
158	  return { kind: "prose", text };
159	};
160	
161	/**
162	 * A leading closed `---` YAML frontmatter block as a preserve segment plus the index just past it,
163	 * or `null` when `lines` doesn't open with one. (Generated API pages don't emit it today, but be safe.)
164	 */
165	const takeFrontmatter = (lines: string[]): { segment: Segment; nextIndex: number } | null => {
166	  if (lines[0] !== "---") return null;
167	  let end = 1;
168	  while (end < lines.length && lines[end] !== "---") end += 1;
169	  if (end >= lines.length) return null;
170	  return {
171	    segment: { kind: "preserve", text: lines.slice(0, end + 1).join("\n") },
172	    nextIndex: end + 1,
173	  };
174	};
175	
176	/** Index just past a fenced code block opening at `start` (includes the closing fence). */
177	const scanFence = (lines: string[], start: number): number => {
178	  let index = start + 1;
179	  while (index < lines.length && !FENCE.test(lines[index])) index += 1;
180	  if (index < lines.length) index += 1; // include the closing fence
181	  return index;
182	};
183	
184	/** Index just past a run of blank lines starting at `start`. */
185	const scanBlankRun = (lines: string[], start: number): number => {
186	  let index = start;
187	  while (index < lines.length && lines[index].trim() === "") index += 1;
188	  return index;
189	};
190	
191	/** Split markdown into ordered, lossless segments. */
192	export function segmentMarkdown(md: string): Segment[] {
193	  const lines = md.split("\n");
194	  const segments: Segment[] = [];
195	  let index = 0;
196	
197	  const frontmatter = takeFrontmatter(lines);
198	  if (frontmatter) {
199	    segments.push(frontmatter.segment);
200	    index = frontmatter.nextIndex;
201	  }
202	
203	  let block: string[] = [];
204	  const flush = (): void => {
205	    if (block.length > 0) {
206	      segments.push(classifyBlock(block));
207	      block = [];
208	    }
209	  };
210	
211	  while (index < lines.length) {
212	    const line = lines[index];
213	
214	    if (FENCE.test(line)) {
215	      flush();
216	      const start = index;
217	      index = scanFence(lines, start);
218	      segments.push({ kind: "preserve", text: lines.slice(start, index).join("\n") });
219	      continue;
220	    }
221	
222	    if (line.trim() === "") {
223	      flush();
224	      const start = index;
225	      index = scanBlankRun(lines, start);
226	      segments.push({ kind: "preserve", text: lines.slice(start, index).join("\n") });
227	      continue;
228	    }
229	
230	    block.push(line);
231	    index += 1;
232	  }
233	  flush();
234	
235	  return segments;
236	}
237	
238	/** Translatable header labels + Description-cell units from one table segment, in document order. */
239	const collectTableUnits = (segment: Extract<Segment, { kind: "table" }>): TranslatableUnit[] => {
240	  const units: TranslatableUnit[] = [];
241	  for (const header of segment.rows[segment.headerRow]) {
242	    if (header !== "") units.push({ text: header, kind: "glossary" });
243	  }
244	  for (let row = 0; row < segment.rows.length; row += 1) {
245	    if (row === segment.headerRow || row === segment.separatorRow) continue;
246	    for (const col of segment.descCols) {
247	      const cell = segment.rows[row][col];
248	      if (cell !== undefined && isTranslatableCell(cell)) {
249	        units.push({ text: cell, kind: cellKind(cell) });
250	      }
251	    }
252	  }
253	  return units;
254	};
255	
256	/** Every translatable unit across the segments, in document order (callers dedupe by content). */
257	export function collectUnits(segments: readonly Segment[]): TranslatableUnit[] {
258	  const units: TranslatableUnit[] = [];
259	  for (const segment of segments) {
260	    if (segment.kind === "glossary" || segment.kind === "prose") {
261	      units.push({ text: segment.text, kind: segment.kind });
262	      continue;
263	    }
264	    if (segment.kind === "table") {
265	      units.push(...collectTableUnits(segment));
266	      continue;
267	    }
268	    if (segment.kind === "callout") {
269	      units.push({ text: segment.label, kind: "glossary" }, { text: segment.note, kind: "prose" });
270	    }
271	  }
272	  return units;
273	}
274	
275	/** Rebuild markdown from segments, resolving each translatable unit through `resolve`. */
276	export function reassemble(segments: readonly Segment[], resolve: Resolve): string {
277	  return segments.map((segment) => renderSegment(segment, resolve)).join("\n");
278	}
279	
280	const renderSegment = (segment: Segment, resolve: Resolve): string => {
281	  switch (segment.kind) {
282	    case "preserve":
283	      return segment.text;
284	    case "glossary":
285	    case "prose":
286	      return resolve(segment.text, segment.kind);
287	    case "table":
288	      return renderTable(segment, resolve);
289	    case "callout":
290	      return [
291	        segment.marker,
292	        segment.alertLine,
293	        `> **${resolve(segment.label, "glossary")}** — ${resolve(segment.note, "prose")}`,
294	      ].join("\n");
295	  }
296	};
297	
298	const renderTable = (segment: Extract<Segment, { kind: "table" }>, resolve: Resolve): string =>
299	  segment.rows
300	    .map((cells, row) => {
301	      const rendered = cells.map((cell, col) => {
302	        if (row === segment.separatorRow) return cell;
303	        if (row === segment.headerRow) return cell === "" ? cell : resolve(cell, "glossary");
304	        if (segment.descCols.includes(col) && isTranslatableCell(cell)) {
305	          return resolve(cell, cellKind(cell));
306	        }
307	        return cell;
308	      });
309	      return rebuildRow(rendered);
310	    })
311	    .join("\n");
