33	/**
34	 * Pull the first `{…}` JSON object out of a model response, tolerating surrounding prose or code
35	 * fences. Returns `null` when no valid object is found.
36	 */
37	export function extractJsonObject(raw: string): Record<string, unknown> | null {
38	  const start = raw.indexOf("{");
39	  const end = raw.lastIndexOf("}");
40	  if (start === -1 || end <= start) return null;
41	  try {
42	    const parsed = JSON.parse(raw.slice(start, end + 1)) as unknown;
43	    return typeof parsed === "object" && parsed !== null
44	      ? (parsed as Record<string, unknown>)
45	      : null;
46	  } catch {
47	    return null;
48	  }
49	}
