315	   * override to also recognize a legacy hash-keyed cache (see `sha256`).
316	   */
317	  isCached?: (key: string, cache: Record<string, string>) => boolean;
318	  /**
319	   * Read `key`'s current cached value, for the passthrough audit. Defaults to `cache[key]`;
320	   * override alongside a custom `isCached` when a legacy cache stores values under `sha256(key)`.
321	   */
322	  cachedValue?: (key: string, cache: Record<string, string>) => string | undefined;
323	  /**
324	   * Per-key verbatim policies (see {@link VerbatimPolicy}), typically produced by
325	   * {@link parseI18nSource} from the same `src/i18n.json` `source` came from. For a locale not
326	   * covered by a key's own tiers, resolution falls through to `defaultVerbatim` (if set), then the
327	   * strict default: identical output is treated as a likely AI failure for every locale.
328	   */
329	  verbatim?: Record<string, VerbatimPolicy>;
330	  /**
331	   * A fallback {@link VerbatimPolicy} applied to every locale not covered by a key's own `verbatim`
332	   * tiers — e.g. a blanket "these language families are close enough to English that an identical
333	   * response isn't necessarily a translator failure" rule, built with {@link localeFamilyGlobs}. A
334	   * key's own `error` tier still wins over this default for a matching locale.
335	   */
336	  defaultVerbatim?: VerbatimPolicy;
337	}
338	
339	/**
340	 * Drop any entry from `cache` whose value is an untranslated echo of its English source and whose
341	 * key resolves to the `"error"` tier for `locale`, so it's retranslated this run instead of sitting
342	 * there looking done forever. A `"warn"`-tier match is left cached but reported. Returns the reset
343	 * and warned keys.
344	 */
345	function resetPassthroughEntries(
346	  cache: Record<string, string>,
347	  source: Record<string, string>,
348	  cachedValue: (key: string, cache: Record<string, string>) => string | undefined,
349	  verbatim: Record<string, VerbatimPolicy>,
350	  defaultVerbatim: VerbatimPolicy | undefined,
351	  locale: string,
352	): { reset: string[]; warned: string[] } {
353	  const reset: string[] = [];
354	  const warned: string[] = [];
355	  for (const key of Object.keys(source)) {
356	    const current = cachedValue(key, cache);
357	    if (current === undefined || !isPassthroughTranslation(source[key], current)) continue;
358	    const action = resolveVerbatimAction(verbatim[key], locale, defaultVerbatim);
359	    if (action === "required" || action === "allow") continue;
360	    if (action === "warn") {
361	      warned.push(key);
362	      continue;
363	    }
364	    delete cache[key];
365	    delete cache[sha256(key)];
366	    reset.push(key);
367	  }
368	  return { reset, warned };
369	}
370	
371	/** Translate `locale`'s missing keys (per `isCached`) and merge/save the result into its cache file. */
372	async function translateLocale(
373	  locale: string,
374	  command: string,
375	  commandArgs: string[],
376	  options: I18nTranslationOptions,
377	  isCached: (key: string, cache: Record<string, string>) => boolean,
378	): Promise<void> {
379	  const cacheFile = resolve(options.cachePath(locale));
380	  let cache: Record<string, string>;
381	  try {
382	    cache = JSON.parse(readFileSync(cacheFile, "utf8"));
383	  } catch {
384	    console.log(`Creating new cache for locale: ${locale}`);
385	    cache = {};
386	  }
387	
388	  const cachedValue = options.cachedValue ?? ((key: string, c: Record<string, string>) => c[key]);
389	  const verbatim = options.verbatim ?? {};
390	  const { reset: resetKeys, warned: warnedResetKeys } = resetPassthroughEntries(
391	    cache,
392	    options.source,
393	    cachedValue,
394	    verbatim,
395	    options.defaultVerbatim,
396	    locale,
397	  );
398	  if (resetKeys.length > 0) {
399	    console.warn(
400	      `⚠ ${locale}: reset ${resetKeys.length} previously-cached entr${resetKeys.length === 1 ? "y" : "ies"} that matched the English source (will retry):\n${formatKeyList(resetKeys)}`,
401	    );
402	  }
403	  if (warnedResetKeys.length > 0) {
404	    console.warn(
405	      `⚠ ${locale}: ${warnedResetKeys.length} cached entr${warnedResetKeys.length === 1 ? "y matches" : "ies match"} the English source (verbatim policy: warn):\n${formatKeyList(warnedResetKeys)}`,
406	    );
407	  }
408	
409	  const requiredKeys = new Set(
410	    Object.keys(options.source).filter(
411	      (key) => resolveVerbatimAction(verbatim[key], locale, options.defaultVerbatim) === "required",
412	    ),
413	  );
414	  let copiedRequired = false;
415	  for (const key of requiredKeys) {
416	    const legacyKey = sha256(key);
417	    if (cache[key] !== options.source[key] || legacyKey in cache) copiedRequired = true;
418	    delete cache[legacyKey];
419	    cache[key] = options.source[key];
420	  }
421	
422	  const missingKeys = Object.keys(options.source).filter(
423	    (key) => !requiredKeys.has(key) && !isCached(key, cache),
424	  );
425	  if (missingKeys.length === 0) {
426	    if (copiedRequired) writeFileSync(cacheFile, JSON.stringify(cache, null, 2) + "\n", "utf8");
427	    console.log(`✓ ${locale}: all strings translated`);
428	    return;
429	  }
430	
431	  console.log(`🔄 ${locale}: translating ${missingKeys.length} new string(s)...`);
432	
433	  const stringsList = missingKeys.map((k) => `- "${k}": "${options.source[k]}"`).join("\n");
434	  const prompt = `Translate these UI strings from English into ${locale} (for a CLI):
435	
436	${stringsList}
437	
438	Respond with a JSON object mapping each original key to its translation, using the exact same keys. Only the translations, nothing else.`;
439	
440	  try {
441	    const result = await spawnPrompt(command, [...commandArgs, "-p"], prompt, `locale "${locale}"`);
442	
443	    const translated = extractJsonObject(result);
444	    if (!translated) {
445	      throw new Error(`AI response could not be parsed as JSON for locale "${locale}".`);
446	    }
447	
448	    const suspectKeys: string[] = [];
449	    const warnedKeys: string[] = [];
450	    let saved = 0;
451	    for (const key of missingKeys) {
452	      const value = translated[key];
453	      if (typeof value !== "string" || value.trim().length === 0) {
454	        suspectKeys.push(`${key} (missing or empty)`);
455	        continue;
456	      }
457	      if (isPassthroughTranslation(options.source[key], value)) {
458	        const action = resolveVerbatimAction(verbatim[key], locale, options.defaultVerbatim);
459	        if (action === "error") {
460	          suspectKeys.push(`${key} (identical to source)`);
461	          continue;
462	        }
463	        if (action === "warn") warnedKeys.push(key);
464	      }
465	      cache[key] = value;
466	      saved++;
467	    }
468	    if (suspectKeys.length > 0) {
469	      console.warn(
470	        `⚠ ${locale}: ${suspectKeys.length} response(s) not cached, will retry next run:\n${formatKeyList(suspectKeys)}`,
471	      );
472	    }
473	    if (warnedKeys.length > 0) {
474	      console.warn(
475	        `⚠ ${locale}: ${warnedKeys.length} response(s) identical to the English source (verbatim policy: warn), cached anyway:\n${formatKeyList(warnedKeys)}`,
476	      );
477	    }
478	
479	    writeFileSync(cacheFile, JSON.stringify(cache, null, 2) + "\n", "utf8");
480	    console.log(`✓ ${locale}: saved ${saved} translation(s)\n`);
481	  } catch (err) {
482	    console.error(`❌ Failed to translate for locale ${locale}:`, err);
483	    process.exit(1);
484	  }
485	}
