487	/**
488	 * Shell out to an AI CLI to translate every source string missing from each target locale's
489	 * on-disk cache, merging the results back in. Shared by `ai/pantoken-ai/scripts/translate.ts` and
490	 * `packages/scaffold/scripts/translate.ts`, whose i18n CLIs both translate a flat key → string map
491	 * the same way, differing only in where the source strings and cache files come from.
492	 *
493	 * Reads `I18N_TRANSLATION_ADAPTER`/`I18N_TRANSLATION_COMMAND`/`I18N_TRANSLATION_COMMAND_ARGS` env
494	 * vars to choose the model/command, matching both callers' existing conventions.
495	 * `I18N_TRANSLATION_FORCE=1` bypasses `isCached` entirely — every key is retranslated and its
496	 * cached value overwritten, even if already present — for a forced refresh after fixing an adapter
497	 * bug or a bad translation. Exits the process with code 1 if a locale's translation request fails.
498	 */
499	export async function runI18nTranslationCli(options: I18nTranslationOptions): Promise<void> {
500	  const adapter = process.env.I18N_TRANSLATION_ADAPTER || "ai";
501	  const command = process.env.I18N_TRANSLATION_COMMAND ?? "claude";
502	  const commandArgs = (process.env.I18N_TRANSLATION_COMMAND_ARGS ?? "")
503	    .split(" ")
504	    .map((p) => p.trim())
505	    .filter((p) => p.length > 0);
506	  const force = process.env.I18N_TRANSLATION_FORCE === "1";
507	  const isCached = force ? () => false : (options.isCached ?? ((key, cache) => key in cache));
508	
509	  console.log(`📋 Translating ${options.label} (${adapter})\n`);
510	
511	  for (const locale of options.targetLocales) {
512	    if (locale === "en") continue; // Skip English, it's the source
513	    await translateLocale(locale, command, commandArgs, options, isCached);
514	  }
515	
516	  console.log(`✨ All translations complete!`);
517	}
