521	/**
522	 * Generate one `LOCALE_<CODE>.ts` module per `<code>.json` file in `<root>/i18n-cache`, plus an
523	 * `index.ts` importing and re-exporting them all as `LOCALES`, into `<outDir>/locales`. Logs a
524	 * one-line summary of the locales it produced (nothing when the cache directory doesn't exist yet).
525	 *
526	 * Shared by `ai/pantoken-ai/scripts/generate.ts` and `packages/scaffold/scripts/generate.ts`, whose
527	 * CLI i18n setups both bake a translated `i18n-cache/` into a generated locale bundle the same way.
528	 *
529	 * @param root - Package root containing `i18n-cache/`.
530	 * @param outDir - The package's `generated/` directory; bundles are written under its `locales/`.
531	 */
532	export function generateLocaleBundles(root: string, outDir: string): void {
533	  const i18nCacheDir = join(root, "i18n-cache");
534	  const localesDir = join(outDir, "locales");
535	  mkdirSync(localesDir, { recursive: true });
536	
537	  const localeMap: Record<string, string> = {};
538	  try {
539	    const cacheFiles = readdirSync(i18nCacheDir);
540	    for (const file of cacheFiles) {
541	      if (!file.endsWith(".json")) continue;
542	      const locale = file.slice(0, -".json".length);
543	      const cachePath = join(i18nCacheDir, file);
544	      const bundle = JSON.parse(readFileSync(cachePath, "utf8"));
545	
546	      // Hyphenated locale tags (e.g. "en-AU") aren't valid JS identifier suffixes.
547	      const varName = `LOCALE_${locale.toUpperCase().replaceAll("-", "_")}`;
548	      const tsContent = `// GENERATED by scripts/generate.ts — do not edit by hand.\nexport const ${varName} = ${JSON.stringify(
549	        bundle,
550	        null,
551	        2,
552	      )} as const;\n`;
553	      writeFileSync(join(localesDir, `${locale}.ts`), tsContent);
554	      localeMap[locale] = varName;
555	    }
556	  } catch {
557	    // i18n-cache directory doesn't exist yet, that's okay
558	  }
559	
560	  const indexContent = `// GENERATED by scripts/generate.ts — do not edit by hand.
561	${Object.entries(localeMap)
562	  .map(([locale, varName]) => `import { ${varName} } from "./${locale}.js";`)
563	  .join("\n")}
564	
565	export const LOCALES: Record<string, Record<string, string>> = {
566	${Object.entries(localeMap)
567	  .map(([locale, varName]) => `  ${JSON.stringify(locale)}: ${varName},`)
568	  .join("\n")}
569	};
570	`;
571	  writeFileSync(join(localesDir, "index.ts"), indexContent);
572	
573	  const locales = Object.keys(localeMap);
574	  if (locales.length > 0) {
575	    console.log(`✓ generated locale bundles for: ${locales.join(", ")}`);
576	  }
577	}
