20	 *     docs/api/classes/Button.md: 18 prose, 5 glossary (15 cached, 8 translated)
21	 *     docs/api/classes/Modal.md: 25 prose, 4 glossary (20 cached, 9 translated)
22	 *     docs/api/typedoc-sidebar.json: 87 labels (65 cached, 22 translated)
23	 *     📄 Summary: 1,450 prose blocks, 445 glossary terms (1,200 cached, 1,347 translated)
24	 *     📋 Summary: 87 labels (65 cached, 22 translated)
25	 *   ✓ ar: rendered in docs/ar/api (3,534 translated, 1,265 cached)
26	 *   ✨ All API locales complete!
27	 */
28	import {
29	  cpSync,
30	  existsSync,
31	  mkdirSync,
32	  readdirSync,
33	  readFileSync,
34	  rmSync,
35	  statSync,
36	  writeFileSync,
37	} from "node:fs";
