39	import { spawnSync } from "node:child_process";
40	import { NON_ROOT_LOCALES } from "../.vitepress/i18n.ts";
41	import { GlossaryTranslationAdapter, createTranslationAdapter } from "./api-translation.ts";
42	import { type Resolve, collectUnits, reassemble, segmentMarkdown } from "./segment-markdown.ts";
