50	const docsRoot = join(import.meta.dirname, "..");
51	const enApiDir = join(docsRoot, "api");
52	const apiDirFor = (locale: string): string => join(docsRoot, locale, "api");
53	
54	const run = (command: string, args: string[]): void => {
55	  const result = spawnSync(command, args, {
56	    cwd: docsRoot,
57	    stdio: "inherit",
58	  });
59	
60	  if (result.status !== 0) {
61	    throw new Error(`${command} ${args.join(" ")} failed with exit code ${result.status ?? -1}`);
62	  }
63	};
64	
65	const walkFiles = (dir: string): string[] => {
66	  if (!existsSync(dir)) {
67	    return [];
68	  }
69	
70	  const files: string[] = [];
71	  for (const name of readdirSync(dir)) {
72	    const fullPath = join(dir, name);
73	    const stat = statSync(fullPath);
74	    if (stat.isDirectory()) {
75	      files.push(...walkFiles(fullPath));
76	    } else {
77	      files.push(fullPath);
78	    }
79	  }
80	  return files;
81	};
82	
83	type SidebarItem = {
84	  text?: string;
85	  link?: string;
86	  items?: SidebarItem[];
87	};
88	
89	// TypeDoc emits absolute API links as `/api/...`; the cloned tree must point at `/<locale>/api/...` or
90	// the localized sidebar navigates back into the English pages. Idempotent — never double-prefixes.
91	const localizeApiLink = (link: string, locale: string): string =>
92	  /^\/api(\/|$)/.test(link) ? `/${locale}${link}` : link;
93	
94	// Same rewrite for absolute `/api/...` links inside the cloned markdown (overview cards, CSS
95	// breadcrumbs). Only touches markdown-link `](…)` and `href="…"` targets, so it leaves relative links
96	// (`../index.md`) and any prose mentioning `/api` alone.
97	const localizeMarkdownApiLinks = (markdown: string, locale: string): string =>
98	  markdown.replace(/(\]\(|href=")\/api(?=[/")])/g, `$1/${locale}/api`);
99	
100	const translateSidebar = (
101	  item: SidebarItem,
102	  translate: (text: string) => string,
103	  locale: string,
104	): SidebarItem => {
105	  const translated: SidebarItem = { ...item };
106	
107	  if (translated.text) {
108	    translated.text = translate(translated.text);
109	  }
110	
111	  if (translated.link) {
112	    translated.link = localizeApiLink(translated.link, locale);
113	  }
114	
115	  if (translated.items) {
116	    translated.items = translated.items.map((child) => translateSidebar(child, translate, locale));
117	  }
118	
119	  return translated;
120	};
121	
122	/** Collect every `text` label in a sidebar tree (for one batched translation pass). */
123	const collectSidebarText = (items: SidebarItem[], out: string[]): void => {
124	  for (const item of items) {
125	    if (item.text) out.push(item.text);
126	    if (item.items) collectSidebarText(item.items, out);
127	  }
128	};
129	
130	// Translated prose occasionally emits literal HTML tags (for example <dialog>), which Vue markdown
131	// parsing treats as real elements and can fail on missing end tags. Escape bare tag tokens in prose
132	// segments while leaving preserved HTML blocks/code fences untouched. A tag with attributes (the
133	// stability-badge pill's `<span class="...">`) is real generated HTML, not a stray mention — its
134	// plain closing partner (`</span>`) must stay unescaped too, or the pair goes unbalanced.
135	const escapeBareHtmlTags = (text: string): string => {
136	  const attributedTagNames = new Set(
137	    [...text.matchAll(/<([A-Za-z][\w-]*)\s[^>]*>/g)].map((match) => match[1]),
138	  );
139	
140	  return text.replace(/<\/?([A-Za-z][\w-]*)>/g, (match, name: string) => {
141	    if (attributedTagNames.has(name)) return match;
142	    return match.startsWith("</") ? `&lt;/${name}&gt;` : `&lt;${name}&gt;`;
143	  });
144	};
