171	/**
172	 * Segment each cloned HU markdown file into prose / deterministic-glossary / verbatim blocks, then
173	 * rewrite it translated in place. Prose is batched + cached through the selected adapter; headings,
174	 * badge pills, and table column labels always go through the glossary (deterministic, keyless, never
175	 * cached); everything else is kept verbatim. Block-level keys survive the scaffolding churn that busted
176	 * whole-file keys. Logs per-file progress incrementally. Returns glossary-term, prose-block, and
177	 * cache/miss counts aggregated across all files.
178	 */
179	const translateMarkdownFiles = async (
180	  markdownFiles: string[],
181	  adapter: ReturnType<typeof createTranslationAdapter>,
182	  memory: TranslationMemory,
183	  locale: string,
184	): Promise<{
185	  glossaryTerms: number;
186	  proseBlocks: number;
187	  proseTranslated: number;
188	  proseCached: number;
189	}> => {
190	  const glossary = new GlossaryTranslationAdapter(locale);
191	  const segmented = markdownFiles.map((filePath) => ({
192	    filePath,
193	    segments: segmentMarkdown(readFileSync(filePath, "utf8")),
194	  }));
195	
196	  let totalGlossaryTerms = 0;
197	  let totalProseBlocks = 0;
198	  let totalProseTranslated = 0;
199	  let totalProseCached = 0;
200	
201	  for (const { filePath, segments } of segmented) {
202	    const fileUnits = collectUnits(segments);
203	
204	    // Translate glossary terms for this file
205	    const glossaryText = new Map<string, string>();
206	    for (const unit of fileUnits) {
207	      if (unit.kind === "glossary" && !glossaryText.has(unit.text)) {
208	        glossaryText.set(unit.text, await glossary.translateText(unit.text));
209	      }
210	    }
211	    totalGlossaryTerms += glossaryText.size;
212	
213	    // Translate prose units for this file
214	    const proseUnits: TranslationUnit[] = fileUnits
215	      .filter((unit) => unit.kind === "prose")
216	      .map((unit) => ({ kind: "prose", source: unit.text }));
217	
218	    const beforeMisses = memory.misses;
219	    const beforeHits = memory.hits;
220	
221	    const proseTranslations = await translateUnits(adapter, memory, proseUnits, {
222	      autosave: true,
223	      locale,
224	      defaultVerbatim: { allow: ["en*"] },
225	    });
226	
227	    const fileProseTranslated = memory.misses - beforeMisses;
228	    const fileProseCached = memory.hits - beforeHits;
229	    totalProseTranslated += fileProseTranslated;
230	    totalProseCached += fileProseCached;
231	
232	    const proseBlockCount = new Set(proseUnits.map((u) => u.source)).size;
233	    totalProseBlocks += proseBlockCount;
234	
235	    // Resolve and write the file
236	    const resolve: Resolve = (text, kind) => {
237	      if (kind === "glossary") {
238	        return glossaryText.get(text) ?? text;
239	      }
240	      const translated = proseTranslations.get(keyFor("prose", text)) ?? text;
241	      return escapeBareHtmlTags(translated);
242	    };
243	    writeFileSync(filePath, localizeMarkdownApiLinks(reassemble(segments, resolve), locale));
244	
245	    // Log per-file progress
246	    const relPath = relative(docsRoot, filePath);
247	    if (proseBlockCount > 0 || glossaryText.size > 0) {
248	      const fileCounts = [
249	        glossaryText.size > 0 && `${glossaryText.size} glossary`,
250	        proseBlockCount > 0 && `${proseBlockCount} prose`,
251	      ]
252	        .filter(Boolean)
253	        .join(", ");
254	      console.log(
255	        `    ${relPath}: ${fileCounts} (${fileProseCached} cached, ${fileProseTranslated} translated)`,
256	      );
257	    }
258	  }
259	
260	  return {
261	    glossaryTerms: totalGlossaryTerms,
262	    proseBlocks: totalProseBlocks,
263	    proseTranslated: totalProseTranslated,
264	    proseCached: totalProseCached,
265	  };
266	};
267	
268	/**
269	 * Collect every sidebar label across all trees, translate them with incremental per-file feedback,
270	 * then rebuild and rewrite each tree from the results. Logs per-file label counts and cache/miss stats.
271	 * Returns aggregated label count and cache/miss stats for the summary log.
272	 */
273	const translateSidebars = async (
274	  sidebarFiles: string[],
275	  adapter: ReturnType<typeof createTranslationAdapter>,
276	  memory: TranslationMemory,
277	  locale: string,
278	): Promise<{ labelCount: number; labelTranslated: number; labelCached: number }> => {
279	  const sidebars = sidebarFiles.map((filePath) => ({
280	    filePath,
281	    tree: JSON.parse(readFileSync(filePath, "utf8")) as SidebarItem[],
282	  }));
283	
284	  let totalLabelCount = 0;
285	  let totalLabelTranslated = 0;
286	  let totalLabelCached = 0;
287	
288	  for (const { filePath, tree } of sidebars) {
289	    const fileLabels: string[] = [];
290	    collectSidebarText(tree, fileLabels);
291	
292	    const beforeMisses = memory.misses;
293	    const beforeHits = memory.hits;
294	
295	    const labelTranslations = await translateUnits(
296	      adapter,
297	      memory,
298	      fileLabels.map((source) => ({ kind: "text", source })),
299	      { locale, defaultVerbatim: { allow: ["en*"] } },
300	    );
301	    const translateLabel = (text: string): string =>
302	      labelTranslations.get(keyFor("text", text)) ?? text;
303	
304	    const translated = tree.map((item) => translateSidebar(item, translateLabel, locale));
305	    writeFileSync(filePath, `${JSON.stringify(translated, null, 2)}\n`);
306	
307	    const fileLabelTranslated = memory.misses - beforeMisses;
308	    const fileLabelCached = memory.hits - beforeHits;
309	    totalLabelTranslated += fileLabelTranslated;
310	    totalLabelCached += fileLabelCached;
311	    totalLabelCount += fileLabels.length;
312	
313	    // Log per-file progress
314	    const relPath = relative(docsRoot, filePath);
315	    console.log(
316	      `    ${relPath}: ${fileLabels.length} label${fileLabels.length === 1 ? "" : "s"} (${fileLabelCached} cached, ${fileLabelTranslated} translated)`,
317	    );
318	  }
319	
320	  return {
321	    labelCount: totalLabelCount,
322	    labelTranslated: totalLabelTranslated,
323	    labelCached: totalLabelCached,
324	  };
325	};
