351	
352	  console.log(
353	    `  📄 Summary: ${proseBlocks} prose block${proseBlocks === 1 ? "" : "s"}, ` +
354	      `${glossaryTerms} glossary term${glossaryTerms === 1 ? "" : "s"} ` +
355	      `(${proseCached} cached, ${proseTranslated} translated)`,
356	  );
357	
358	  // 2. Sidebar labels (logs per-file progress internally)
359	  const { labelCount, labelTranslated, labelCached } = await translateSidebars(
360	    sidebarFiles,
361	    adapter,
362	    memory,
