367	    `  📋 Summary: ${labelCount} label${labelCount === 1 ? "" : "s"} ` +
368	      `(${labelCached} cached, ${labelTranslated} translated)`,
369	  );
370	
371	  memory.save();
372	  const totalTranslated = proseTranslated + labelTranslated;
373	  const totalCached = proseCached + labelCached;
374	  console.log(
375	    `✓ ${locale}: rendered in ${relative(docsRoot, localeApiDir)} ` +
376	      `(${totalTranslated} translated, ${totalCached} cached)\n`,
377	  );
378	};
